import pytest


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping the high bits around.

    Expects 0 <= x <= 255 and 0 <= k <= 7. The result is always in 0..255.
    """
    return ((x << k) | (x >> (8 - k))) & 0xFF


def test_rotl8_zero_shift_is_identity() -> None:
    for x in (0, 1, 0x80, 0xB5, 255):
        assert rotl8(x, 0) == x


def test_rotl8_simple_shift_without_wrap() -> None:
    assert rotl8(0b00000001, 1) == 0b00000010
    assert rotl8(0b00000011, 2) == 0b00001100


def test_rotl8_wraps_high_bits() -> None:
    assert rotl8(0b10000001, 1) == 0b00000011
    assert rotl8(0b10000000, 1) == 0b00000001
    assert rotl8(0x81, 4) == 0x18
    assert rotl8(0xB5, 3) == 0xAD
    assert rotl8(1, 7) == 128


def test_rotl8_extremes() -> None:
    assert rotl8(0, 5) == 0
    for k in range(8):
        assert rotl8(255, k) == 255


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= 255


def test_rotl8_preserves_popcount() -> None:
    for x in range(256):
        for k in range(8):
            assert rotl8(x, k).bit_count() == x.bit_count()


def test_rotl8_inverse_rotation() -> None:
    for x in range(256):
        for k in range(1, 8):
            assert rotl8(rotl8(x, k), 8 - k) == x


@pytest.mark.parametrize("a", range(8))
@pytest.mark.parametrize("b", range(8))
def test_rotl8_composes(a: int, b: int) -> None:
    for x in (0, 1, 0x5A, 0x80, 0xB5, 0xFF):
        assert rotl8(rotl8(x, a), b) == rotl8(x, (a + b) % 8)
